let sequence=0;
const pending=new Map<number,{resolve:(value:any)=>void;reject:(error:Error)=>void}>();
window.companionReply=({id,result,error})=>{const p=pending.get(id);if(!p)return;pending.delete(id);error?p.reject(new Error(error)):p.resolve(result);};
function call<T>(method:string,args:object={}):Promise<T>{if(!window.CompanionNative)return Promise.reject(new Error('请在 Companion Android 应用中使用此功能。'));return new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});window.CompanionNative!.call(id,method,JSON.stringify(args));});}
